head.script:
window.onunload = function() {
    // 기업검색에서도 쓰기 때문에 try catch 로 묶는다
    try {
        opener.fn_getBeforeRadioBtn("ALL");
    } catch (E) {

    }
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (opener.scwin.vScrenID === "ULDFIS00600.gfm") {
        txb_IND_PTTN.setValue(opener.cmb_IND_PTTN.getValue());
        txb_ACNTG_BAS_TYP.setValue(opener.cmb_ACNTG_BAS_TYP.getValue());
        txb_INDVDL_CONN_TP.setValue(opener.cmb_INDVDL_CONN_TP.getValue());
    } else if (opener.scwin.vScrenID === "ULDFIS00600_P2.gfm" || opener.scwin.vScrenID === "ULDFIS00600_P5.gfm") {
        txb_IND_PTTN.setValue(opener.txb_IND_PTTN.getValue());
        txb_ACNTG_BAS_TYP.setValue(opener.txb_ACNTG_BAS_TYP.getValue());
        txb_INDVDL_CONN_TP.setValue(opener.txb_INDVDL_CONN_TP.getValue());
    }

    // 계정유형 조회
    await scwin.getDtsAccntPttn();

    // 조회
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Acnt_OnLoadError
 * @description dts_Acnt 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Acnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.dts_Acnt_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Acnt_OnLoadCompleted
 * @description dts_Acnt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Acnt.errorMsg) {
            await $c.win.alert(dts_Acnt.errorMsg);
        }
        // trv_Year.ExpandLevel = 1;
        // trv_Year.index = 1;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.dts_Acnt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        // opener.fn_getBeforeRadioBtn("ALL");
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        // 확인버튼 클릭
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name trv_Year_OnDblClick
 * @description trv_Year 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trv_Year_OnDblClick = async function() {
    try {
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.trv_Year_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_ACCNT_NM_onkeydown
 * @description txb_ACCNT_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ACCNT_NM_onkeydown = async function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.txb_ACCNT_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // 조회 버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name cmb_ACCNT_PTTN_onselchange
 * @description cmb_ACCNT_PTTN onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ACCNT_PTTN_onselchange = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P3.cmb_ACCNT_PTTN_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDtsAccntPttn
 * @description 재무유형 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDtsAccntPttn = async function() {
    const sbmOptions = {
        id : "sbm_dts_AccntPttn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AccntPttn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_Acnt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Acnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_Acnt.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    const nRow = dts_Acnt.getRowPosition();
    if (nRow < 1) {
        return;
    }
    const sItemCd = dts_Acnt.getCellData(nRow, "ACCNT_PTTN") + dts_Acnt.getCellData(nRow, "ACCNT_CD");
    const sItemNM = dts_Acnt.getCellData(nRow, "ACCNT_NM");
    const sItemTyp = "1"; // 0:년도, 1:계정, 3:회사
    const sAxisTyp = "1"; // AXIS_TYP  1:기준, 2: 가로, 3:세로
    const sColYear = "0000"; // COL_YEAR

    if (sItemCd !== "") {
        const arrPar = new Array();
        arrPar[0] = {
            ITEM_CD: sItemCd,
            ITEM_NM: sItemNM,
            ITEM_TYP: sItemTyp,
            AXIS_TYP: sAxisTyp,
            COL_YEAR: sColYear
        };
        $c.frame.path("../").fn_SetAxisInfo(arrPar);
    }
    await $c.win.closePopup();
};
